package main

import (
	"bytes"
	"flag"
	"fmt"
	"io/fs"
	"os"

	"github.com/ishuar/tfskel/cmd"
	"github.com/spf13/cobra"
	"github.com/spf13/cobra/doc"
)

// header is prepended to every generated file so readers (and reviewers) see
// at a glance that edits belong in cmd/, not here.
const header = "<!-- Generated by `make docs` from the cobra command tree. Do not edit by hand: change the Long/Example strings in cmd/ and regenerate. -->\n\n"

// pagePattern matches the files this tool owns inside the output directory.
// cobra/doc names each page "<root>_<sub>_<subsub>.md" after the command path,
// and the root command is tfskel, so this is the full set of generated pages.
// Anything else in the directory (hand-written notes, assets) is never touched.
const pagePattern = "tfskel*.md"

func main() {
	out := flag.String("out", "docs/reference", "directory to write the Markdown reference into")
	flag.Parse()

	if err := run(*out); err != nil {
		fmt.Fprintln(os.Stderr, "gendocs:", err)
		os.Exit(1)
	}
}

// run regenerates the reference into out. out comes from the command line and
// this tool deletes files, so every delete and rewrite goes through an os.Root
// scoped to out: a bad -out value can only ever affect that one directory.
// cobra/doc itself takes a plain path, so creation is the one step outside the
// root; it only ever creates "<command path>.md" files.
func run(out string) (err error) {
	if err := os.MkdirAll(out, 0755); err != nil {
		return fmt.Errorf("create %s: %w", out, err)
	}
	root, err := os.OpenRoot(out)
	if err != nil {
		return fmt.Errorf("open %s: %w", out, err)
	}
	defer func() {
		if cerr := root.Close(); cerr != nil && err == nil {
			err = fmt.Errorf("close %s: %w", out, cerr)
		}
	}()

	// Remove previously generated pages so a renamed or removed command does
	// not leave an orphan behind.
	previous, err := fs.Glob(root.FS(), pagePattern)
	if err != nil {
		return fmt.Errorf("glob previous docs: %w", err)
	}
	for _, page := range previous {
		if err := root.Remove(page); err != nil {
			return fmt.Errorf("remove previous doc %s: %w", page, err)
		}
	}

	tree := cmd.NewRootCmd()
	// cobra adds the completion command lazily inside Execute(), so a freshly
	// built tree does not have it. Add it here so the reference lists the same
	// commands as `tfskel --help`.
	tree.InitDefaultCompletionCmd()
	disableAutoGenTag(tree)

	prepend := func(string) string { return header }
	link := func(name string) string { return name }
	if err := doc.GenMarkdownTreeCustom(tree, out, prepend, link); err != nil {
		return fmt.Errorf("generate markdown: %w", err)
	}
	return normalizeTrailingNewlines(root)
}

// normalizeTrailingNewlines rewrites each generated page to end with exactly
// one newline. cobra/doc emits a trailing blank line, which editors and
// end-of-file hooks commonly strip; pinning the ending here keeps regeneration
// byte-identical to what contributors commit, so docs-check only fails on
// real drift.
func normalizeTrailingNewlines(root *os.Root) error {
	pages, err := fs.Glob(root.FS(), pagePattern)
	if err != nil {
		return fmt.Errorf("glob generated docs: %w", err)
	}
	for _, page := range pages {
		b, err := fs.ReadFile(root.FS(), page)
		if err != nil {
			return fmt.Errorf("read %s: %w", page, err)
		}
		trimmed := append(bytes.TrimRight(b, "\n"), '\n')
		if bytes.Equal(b, trimmed) {
			continue
		}
		f, err := root.OpenFile(page, os.O_WRONLY|os.O_TRUNC, 0644)
		if err != nil {
			return fmt.Errorf("open %s for writing: %w", page, err)
		}
		_, werr := f.Write(trimmed)
		if cerr := f.Close(); werr == nil {
			werr = cerr
		}
		if werr != nil {
			return fmt.Errorf("write %s: %w", page, werr)
		}
	}
	return nil
}

// disableAutoGenTag turns off cobra's per-file "Auto generated on <date>"
// footer on every command. The date changes on each run, which would make
// the CI drift check fail on a no-op regeneration.
func disableAutoGenTag(c *cobra.Command) {
	c.DisableAutoGenTag = true
	for _, sub := range c.Commands() {
		disableAutoGenTag(sub)
	}
}
